-- =========================================================
-- 20261013120000_production_catalog_sync.sql
--
-- Production catalog reconciliation (Phase 4, 2026-10-13).
--
-- A parallel expansion effort built extensive market data
-- directly in the production database (out-of-band, 2026-10-05
-- through 2026-10-10): the POP/tile material catalogs for 39
-- markets, screeding surface-prep configs for 40 markets, price
-- books for 40 markets, and the scan source registry. None of it
-- was captured in repository migrations, so fresh preview
-- databases built from migrations diverged from production.
--
-- This migration restores reproducibility: it is GENERATED from a
-- read-only production export taken 2026-10-13 via the Supabase
-- Management API, and it converges every database to the
-- production catalog:
--
-- - fresh preview DBs receive the full catalog
-- - production itself is untouched (guards skip existing rows;
--   content keyed updates only restore values production already
--   has, including after the role remaps in 20261013100000)
--
-- Guards used:
-- - estimation_materials   ON CONFLICT (slug) DO NOTHING
-- - estimation_prices      resolved by material slug, WHERE NOT EXISTS
-- - market_material_roles ON CONFLICT (market, role) DO UPDATE (content only)
-- - screeding_system_config ON CONFLICT (market, system_type) DO UPDATE
-- - price_scan_sources     WHERE NOT EXISTS (market, material_slug, retailer)
-- - pop_workflows / tile_sizes  ON CONFLICT (natural key) DO NOTHING
-- - pop_materials          ON CONFLICT (name, workflow) DO UPDATE (content;
--                         aligns phase12-seeded NG rows with production values)
-- - tile_materials         ON CONFLICT (name) DO UPDATE (content;
--                         aligns phase12-seeded NG rows with production values)
--
-- One correction applied to the exported data before writing:
-- the ZA screeding putty row is corrected to the verified Gyproc
-- RhinoLite datasheet yield (2.5 kg/m² at 2.5 mm -> 16 m² per
-- 40 kg retail bag; production carried 10 m²). Verified 2026-10-13.
--
-- No destructive changes; no secrets; prices keep their original
-- provenance (price_source / scan_confidence / notes).
-- =========================================================

-- ── 1. estimation_materials (387 rows) ──
ON CONFLICT (slug) DO NOTHING;

-- ── 2. estimation_prices (375 active rows; ref_id resolved by slug) ──
SELECT v.price_type, m.id, v.price::numeric, v.currency, v.effective_date::date, v.notes, v.is_active, v.price_source, v.last_scanned_at, v.scan_confidence, v.scan_source, v.market, v.created_at::timestamptz, v.updated_at::timestamptz
FROM (VALUES
